/**
 * Native HTTP transport used by the shared OAuth/OIDC core.
 *
 * Implementations must not follow redirects. They must propagate cancellation
 * and return redirect responses to the core without forwarding credentials.
 */
public protocol NativeHttpTransport: AnyObject, Sendable {
    
    /**
     * Executes one request and returns its response or transport error.
     */
    func execute(request: FfiHttpRequest, cancellation: FfiCancellationHandle) async throws  -> FfiHttpResponse
    
}
/**
 * Native HTTP transport used by the shared OAuth/OIDC core.
 *
 * Implementations must not follow redirects. They must propagate cancellation
 * and return redirect responses to the core without forwarding credentials.
 */
open class NativeHttpTransportImpl: NativeHttpTransport, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_appauth_rust_fn_clone_nativehttptransport(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_appauth_rust_fn_free_nativehttptransport(handle, $0) }
    }

    

    
    /**
     * Executes one request and returns its response or transport error.
     */
open func execute(request: FfiHttpRequest, cancellation: FfiCancellationHandle)async throws  -> FfiHttpResponse  {
    return
        try  await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_appauth_rust_fn_method_nativehttptransport_execute(
                        self.uniffiCloneHandle(),FfiConverterTypeFfiHttpRequest_lower(request),FfiConverterTypeFfiCancellationHandle_lower(cancellation)
                )
            },
            pollFunc: ffi_appauth_rust_rust_future_poll_rust_buffer,
            completeFunc: ffi_appauth_rust_rust_future_complete_rust_buffer,
            freeFunc: ffi_appauth_rust_rust_future_free_rust_buffer,
            liftFunc: FfiConverterTypeFfiHttpResponse_lift,
            errorHandler: FfiConverterTypeFfiError_lift
        )
}
    

    
}



// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceNativeHttpTransport {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceNativeHttpTransport = UniffiVTableCallbackInterfaceNativeHttpTransport(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeNativeHttpTransport.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface NativeHttpTransport: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeNativeHttpTransport.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface NativeHttpTransport: handle missing in uniffiClone")
            }
        },
        execute: { (
            uniffiHandle: UInt64,
            request: RustBuffer,
            cancellation: UInt64,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> FfiHttpResponse in
                guard let uniffiObj = try? FfiConverterTypeNativeHttpTransport.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.execute(
                     request: try FfiConverterTypeFfiHttpRequest_lift(request),
                     cancellation: try FfiConverterTypeFfiCancellationHandle_lift(cancellation)
                )
            }

            let uniffiHandleSuccess = { (returnValue: FfiHttpResponse) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypeFfiHttpResponse_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeFfiError_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceNativeHttpTransport> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceNativeHttpTransport>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitNativeHttpTransport() {
    uniffi_appauth_rust_fn_init_callback_vtable_nativehttptransport(UniffiCallbackInterfaceNativeHttpTransport.vtablePtr)
}

