    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidRequest(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidResponse(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .AuthorizationServer(
            code: try FfiConverterString.read(from: &buf), 
            description: try FfiConverterOptionString.read(from: &buf)
            )
        case 4: return .ClientRegistrationServer(
            code: try FfiConverterString.read(from: &buf), 
            description: try FfiConverterOptionString.read(from: &buf)
            )
        case 5: return .HttpStatus(
            status: try FfiConverterUInt16.read(from: &buf)
            )
        case 6: return .Transport
        case 7: return .TransportFailure(
            try FfiConverterString.read(from: &buf)
            )
        case 8: return .Cancelled
        case 9: return .Clock
        case 10: return .Randomness
        case 11: return .Internal(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidRequest(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .InvalidResponse(v1):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .AuthorizationServer(code,description):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(code, into: &buf)
            FfiConverterOptionString.write(description, into: &buf)
            
        
        case let .ClientRegistrationServer(code,description):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(code, into: &buf)
            FfiConverterOptionString.write(description, into: &buf)
            
        
        case let .HttpStatus(status):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(status, into: &buf)
            
        
        case .Transport:
            writeInt(&buf, Int32(6))
        
        
        case let .TransportFailure(v1):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(8))
        
        
        case .Clock:
            writeInt(&buf, Int32(9))
        
        
        case .Randomness:
            writeInt(&buf, Int32(10))
        
        
        case let .Internal(v1):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
